1	import { addMonths } from './dates.js';
2	
3	/** Billing cycles a plan can have. */
4	export const CYCLE = Object.freeze({ MONTH: 'monthly', YEAR: 'yearly' });
5	
6	/** Every supported cycle, as stored in the subscriptions file. */
7	export const CYCLES = Object.freeze(Object.values(CYCLE));
8	
9	const MONTHS_PER_CHARGE = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 12 };
10	
11	/**
12	 * What a plan costs per month, in whole cents (cut to the cent).
13	 * @param {{ price: number, cycle: string }} sub
14	 * @returns {number}
15	 */
16	export function monthlyCents(sub) {
17	  return Math.floor(sub.price / MONTHS_PER_CHARGE[sub.cycle]);
18	}
19	
20	/**
21	 * The date of a plan's next charge on or after `today` ('YYYY-MM-DD').
22	 * Charges fall on the day of the month of the first charge (`since`), or the last day of a shorter month.
23	 * @param {{ cycle: string, since: string }} sub
24	 * @param {string} today
25	 * @returns {string}
26	 */
27	export function nextCharge(sub, today) {
28	  const step = MONTHS_PER_CHARGE[sub.cycle];
29	  let n = 0;
30	  let date = sub.since;
31	  while (date < today) {
32	    n += 1;
33	    date = addMonths(sub.since, n * step);
34	  }
35	  return date;
36	}
