1	// All dates are 'YYYY-MM-DD' strings and all maths is done in UTC, so the local time zone never matters.
2	
3	const DAY_MS = 24 * 60 * 60 * 1000;
4	const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
5	
6	function toUtc(iso) {
7	  const [y, m, d] = iso.split('-').map(Number);
8	  return Date.UTC(y, m - 1, d);
9	}
10	
11	function fromUtc(ms) {
12	  return new Date(ms).toISOString().slice(0, 10);
13	}
14	
15	/**
16	 * Check a date typed by a person. Returns the same 'YYYY-MM-DD' string, or null if it is not a real date.
17	 * @param {string} text
18	 * @returns {string | null}
19	 */
20	export function parseDate(text) {
21	  const s = String(text).trim();
22	  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
23	  return fromUtc(toUtc(s)) === s ? s : null;
24	}
25	
26	/**
27	 * Today's date in UTC.
28	 * @returns {string}
29	 */
30	export function todayIso() {
31	  return new Date().toISOString().slice(0, 10);
32	}
33	
34	/**
35	 * Add whole days: addDays('2026-12-30', 3) -> '2027-01-02'.
36	 * @param {string} iso
37	 * @param {number} days
38	 * @returns {string}
39	 */
40	export function addDays(iso, days) {
41	  return fromUtc(toUtc(iso) + days * DAY_MS);
42	}
43	
44	/**
45	 * Add whole months, keeping the day of the month or using the last day of a shorter month:
46	 * addMonths('2026-01-31', 1) -> '2026-02-28'.
47	 * @param {string} iso
48	 * @param {number} months
49	 * @returns {string}
50	 */
51	export function addMonths(iso, months) {
52	  const [y, m, d] = iso.split('-').map(Number);
53	  const first = new Date(Date.UTC(y, m - 1 + months, 1));
54	  const lastDay = new Date(Date.UTC(first.getUTCFullYear(), first.getUTCMonth() + 1, 0)).getUTCDate();
55	  return fromUtc(Date.UTC(first.getUTCFullYear(), first.getUTCMonth(), Math.min(d, lastDay)));
56	}
57	
58	/**
59	 * Whole days from one date to another (negative if `to` is earlier).
60	 * @param {string} from
61	 * @param {string} to
62	 * @returns {number}
63	 */
64	export function daysBetween(from, to) {
65	  return Math.round((toUtc(to) - toUtc(from)) / DAY_MS);
66	}
67	
68	/**
69	 * Short label for people: '2026-11-02' -> '2 Nov'.
70	 * @param {string} iso
71	 * @returns {string}
72	 */
73	export function shortLabel(iso) {
74	  const [, m, d] = iso.split('-').map(Number);
75	  return `${d} ${MONTH_NAMES[m - 1]}`;
76	}
