1	/**
2	 * Parse a euro amount typed by a person ("12", "12.5", "1,299.00") into whole cents.
3	 * Returns null when the text is not an amount.
4	 * @param {string} text
5	 * @returns {number | null}
6	 */
7	export function parseEuros(text) {
8	  const m = /^(\d{1,3}(?:,\d{3})+|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
9	  if (!m) return null;
10	  return Number(m[1].replace(/,/g, '')) * 100 + Number((m[2] ?? '').padEnd(2, '0'));
11	}
12	
13	/**
14	 * Format whole cents as euros: 123456 -> "€1,234.56".
15	 * @param {number} cents
16	 * @returns {string}
17	 */
18	export function formatEuros(cents) {
19	  const sign = cents < 0 ? '-' : '';
20	  const abs = Math.abs(cents);
21	  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
22	  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
23	}
24	
25	/**
26	 * Format whole cents as a plain decimal for files: 123456 -> "1234.56".
27	 * @param {number} cents
28	 * @returns {string}
29	 */
30	export function plainEuros(cents) {
31	  return (cents / 100).toFixed(2);
32	}
