1	import { nextCharge } from './cycles.js';
2	import { plainEuros } from './money.js';
3	
4	const HEADER = ['name', 'price', 'cycle', 'monthly_cost', 'next_charge'];
5	
6	// how many months one charge pays for
7	const MONTHS = { monthly: 1, yearly: 12 };
8	
9	function cell(value) {
10	  const s = String(value);
11	  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
12	}
13	
14	/**
15	 * Subscriptions as CSV for a spreadsheet, one row per plan, with its monthly cost and next charge.
16	 * @param {Array<{ name: string, price: number, cycle: string, since: string }>} subs
17	 * @param {string} today 'YYYY-MM-DD'
18	 * @returns {string}
19	 */
20	export function toCsv(subs, today) {
21	  const lines = [HEADER.join(',')];
22	  for (const sub of subs) {
23	    const monthly = Math.floor(sub.price / MONTHS[sub.cycle]);
24	    lines.push([sub.name, plainEuros(sub.price), sub.cycle, plainEuros(monthly), nextCharge(sub, today)].map(cell).join(','));
25	  }
26	  return lines.join('\n') + '\n';
27	}
